visual.browserEval:
for (const locale of ['en', 'zh-cn']) {
  const tab = await browser.open({ name: 'finf1157-current-' + locale, url: 'http://127.0.0.1:45457/' + locale + '/specifications/as-hook/', viewport: { width: 1280, height: 900 } });
  await tab.waitForSelector('main');
  print({ locale, url: await tab.url(), observation: await tab.observe({ includeAll: true }), errors: await tab.errors() });
  print(await tab.screenshot({ fullPage: true }));
}
